named-intermediate-column-default.specification:
yamaa: "1.0"
type: spec
domain: ADEX
keys: [STUDYID, USUBJID, PARAMCD]
input: {DM: dm.csv, EX: ex.csv}
base: DM
output: {path: result.csv, columns: [STUDYID, USUBJID, PARAMCD, AVALC]}
intermediates:
  - {id: FIRST_DOSE, dataset: EX, key: [USUBJID], order_by: [EX.EXSTDTC], keep: first}
columns:
  - {name: STUDYID, type: str, derivation: DM.STUDYID}
  - {name: USUBJID, type: str, derivation: DM.USUBJID}
  - {name: PARAMCD, type: str}
  - {name: AVALC, type: str, derivation: FIRST_DOSE.EXSTDTC}
rows:
  - {id: first, dataset: DM, derivations: {PARAMCD: "'FIRSTDT'"}}
  - {id: count, dataset: DM, derivations: {PARAMCD: "'NDOSE'", AVALC: "'2'"}}

