aggregate-column-default-refused.specification:
yamaa: "1.0"
type: spec
domain: ADEX
keys: [STUDYID, USUBJID, PARAMCD]
input: {DM: dm.csv, EX: {path: ex.csv, key: [STUDYID, USUBJID]}}
base: DM
output: {path: result.csv, columns: [STUDYID, USUBJID, PARAMCD, AVAL]}
columns:
  - {name: STUDYID, type: str, derivation: DM.STUDYID}
  - {name: USUBJID, type: str, derivation: DM.USUBJID}
  - {name: PARAMCD, type: str}
  - {name: AVAL, type: int, derivation: {aggregate: 'COUNT(EX.*)'}}
rows:
  - {id: ndose, dataset: DM, derivations: {PARAMCD: "'NDOSE'"}}
  - {id: fixed, dataset: DM, derivations: {PARAMCD: "'FIXED'", AVAL: 7}}

wrapped-template-key.specification:
yamaa: "1.0"
type: spec
domain: TEST
keys: [ID, SECTION]
input:
  SRC: {path: src.csv, types: {K: int}}
  DONOR: {path: donor.csv, types: {CODE: int}}
output: {path: result.csv, columns: [ID, SECTION, LABEL]}
intermediates:
  - {id: P, dataset: DONOR, key: {CODE: MATCHK}}
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: SECTION, type: str}
  - {name: RAW, type: int, derivation: SRC.K}
  - {name: SHIFT, type: int, derivation: 1}
  - {name: MATCHK, type: int, derivation: 'RAW + SHIFT'}
  - {name: LABEL, type: str, derivation: {str_template: 'value:{P.V}'}}
rows:
  - {id: first, dataset: SRC, derivations: {SECTION: "'first'"}}
  - {id: fixed, dataset: SRC, derivations: {SECTION: "'fixed'", LABEL: "'fixed'"}}

wrapped-extract-key.specification:
yamaa: "1.0"
type: spec
domain: TEST
keys: [ID, SECTION]
input:
  SRC: {path: src.csv, types: {K: int}}
  DONOR: {path: donor.csv, types: {CODE: int}}
output: {path: result.csv, columns: [ID, SECTION, LABEL]}
intermediates:
  - {id: P, dataset: DONOR, key: {CODE: MATCHK}}
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: SECTION, type: str}
  - {name: RAW, type: int, derivation: SRC.K}
  - {name: SHIFT, type: int, derivation: 1}
  - {name: MATCHK, type: int, derivation: 'RAW + SHIFT'}
  - {name: LABEL, type: str, derivation: {str_extract: {source: P.V, pattern: '^(.+)$', group: 1}}}
rows:
  - {id: first, dataset: SRC, derivations: {SECTION: "'first'"}}
  - {id: fixed, dataset: SRC, derivations: {SECTION: "'fixed'", LABEL: "'fixed'"}}
